// =============================================================================
//  LocalizationES.cpp  -- The Hell 4 -- Spanish overlay  (th4)
//  LANG_ES = 4. Latin script, REAL CP1252 ACCENTS (since 2026-10-07; it was ASCII-folded before).
//
//  Re-spelt by the loc toolkit (2026-10-07) from the previous, unaccented Spanish text: same wording, with
//  the tildes, n-tilde, u-diaeresis and the inverted question/exclamation marks restored, plus the rows the
//  old file lacked (bosses, newer UI strings) and corrections from Spanish players. From now on this file IS
//  the source: edit it by hand, following the encoding rules below.
//
//  ---- ENCODING ------------------------------------------------------------
//  * Byte encoding is CP1252. Read/write this file in Python with 'latin-1' for raw bytes.
//  * The only non-ASCII bytes allowed are the ones the Spanish fonts carry:
//      a/e/i/o/u-acute \xE1 \xE9 \xED \xF3 \xFA   n-tilde \xF1   u-diaeresis \xFC
//      capitals        \xC1 \xC9 \xCD \xD3 \xDA   \xD1           \xDC
//      inverted ? \xBF   inverted ! \xA1
//    Never 0x80..0x9F (typographic quotes, dashes, the euro sign...): 0x80..0x8B are colour codes for the
//    in-game text loops (Tooltip.cpp IsColorControlByte) and none of them has a glyph. Use ASCII " ' -.
//  * *** THE GREEDY-HEX C2022 TRAP APPLIES ***: a \x escape eats every following ASCII hex digit
//    INCLUDING a-f / A-F: write "\xE9""e", never the escape glued to a hex letter.
//    Check with regex  \\x[0-9A-Fa-f]{2}[0-9A-Fa-f]  -> must be 0 hits.
//  * The in-game CEL fonts are CAPS-ONLY; lowercase bytes alias the uppercase glyph.
//  * ES_Menu is drawn ONLY by the META-MENU atlas (ui_art font16/24/30/42, stock cells, raw bytes): the stock
//    atlas already has every Spanish letter. Keys must byte-exactly match the English source literal.
//
//  ---- FONTS ---------------------------------------------------------------
//  TH4loc_esp.mor (mounted at 8900 only when language == ES) carries the voice dub AND the three accent fonts:
//  data\medtexts.cel + data\bigtgold.cel = the Portuguese CELs, ctrlpan\smaltext.cel = the Croatian CEL + N-tilde,
//  U-diaeresis and the inverted marks (letterIDs 111..114). Tables: Codepage_Spanish +
//  FontIndex{Small,Mid,Big}_SpanishAccents / FontWidth{Mid,Big}_SpanishAccents in dataseg.cpp. The CELs and those
//  tables are a matched pair. (The *_Spanish fold tables are now Italian's and Swahili's only.)
//
//  ---- WIDTH-LIMITED ROWS ----------------------------------------------------
//  * Shop / towner dialog rows (PlayerTrade.cpp SetDialogRow) must fit 257 px (small box) / 577 px (big box)
//    in the small font; towner names (Towner.Name) are char[32].
//  * Game-changer option rows "...: %s" must fit the list: no wider than "Objetos Imperecederos: N".
//  * Spellbook description lines (SpellPanel.cpp DrawSpellBook / WriteSummonSpellBookInfo) must fit 258 px in the
//    small font (SpellBookTextRect, Panel.cpp ~1277); a 2-3 line description may move words between its lines.
//  * OK / Cancel buttons: no wider than "Cancela" ("Cancelar" was cut).
//  The loc toolkit's check_batch.py enforces all of these (lang_es.py extra_check).
//
//  ---- CONVENTIONS -----------------------------------------------------------
//  * "Relict of X" = "Reliquia de X"; classic mode swaps "Reliquia" for "Pergamino" (Item.cpp).
//  * Game Changers = "Alteraciones" (the Spanish players' term); Dark Campaign = "Campa\xF1""a Oscura".
//
//  English source is inviolable -- translate via these overlays only.
// =============================================================================
#include "stdafx.h"

struct UiStr  { const char* en; const char* tr; }; // .tr column holds the Spanish text
struct IdxStr { int index; const char* tr; };

// MUST stay in sync with the master enum in Localization.cpp -- the ids are array
// indices shared across translation units.
enum {
	OVL_UI = 0, OVL_MENU, OVL_UNIQUE_ITEM, OVL_AFFIX_PREFIX, OVL_AFFIX_SUFFIX,
	OVL_BASE_ITEM, OVL_BASE_NAME2, OVL_ELEMENT, OVL_SPICIES, OVL_ICEAGE,
	OVL_SPELL, OVL_SPELL_NOM, OVL_PERK_NAME, OVL_PERK_DESC, OVL_WARP,
	OVL_WARP_OBL,
	OVL_STR_COUNT
};
enum { OVL_SPEECH = 0, OVL_ONSCREEN, OVL_QUEST, OVL_IDX_COUNT };

// A lone placeholder row ({ 0, 0 } / { -1, 0 }) counts as 0 rows => English fallback.
static bool isPlaceholder( const UiStr&  r ) { return r.en == 0; }
static bool isPlaceholder( const IdxStr& r ) { return r.index < 0 && r.tr == 0; }

template<typename T, size_t N>
static int countRows( const T (&arr)[N] )
{
	if( N == 1 && isPlaceholder( arr[0] ) ) return 0;
	return (int)N;
}

