const UiStr* ES_GetStrTable( int ovlId, int* n )
{
	switch( ovlId ){
		case OVL_UI:           *n = countRows( ES_Ui ); return ES_Ui;
		case OVL_MENU:         *n = countRows( ES_Menu ); return ES_Menu;
		case OVL_UNIQUE_ITEM:  *n = countRows( ES_UniqueItem ); return ES_UniqueItem;
		case OVL_AFFIX_PREFIX: *n = countRows( ES_AffixPrefix ); return ES_AffixPrefix;
		case OVL_AFFIX_SUFFIX: *n = countRows( ES_AffixSuffix ); return ES_AffixSuffix;
		case OVL_BASE_ITEM:    *n = countRows( ES_BaseItem ); return ES_BaseItem;
		case OVL_BASE_NAME2:   *n = countRows( ES_BaseName2 ); return ES_BaseName2;
		case OVL_ELEMENT:      *n = countRows( ES_Element ); return ES_Element;
		case OVL_SPICIES:      *n = countRows( ES_Spicies ); return ES_Spicies;
		case OVL_ICEAGE:       *n = countRows( ES_IceAge ); return ES_IceAge;
		case OVL_SPELL:        *n = countRows( ES_Spell ); return ES_Spell;
		case OVL_SPELL_NOM:    *n = countRows( ES_SpellNom ); return ES_SpellNom;
		case OVL_PERK_NAME:    *n = countRows( ES_PerkName ); return ES_PerkName;
		case OVL_PERK_DESC:    *n = countRows( ES_PerkDesc ); return ES_PerkDesc;
		case OVL_WARP:         *n = countRows( ES_Warp ); return ES_Warp;
		case OVL_WARP_OBL:     *n = countRows( ES_WarpOblique ); return ES_WarpOblique;
	}
	*n = 0; return 0;
}

const IdxStr* ES_GetIdxTable( int ovlId, int* n )
{
	switch( ovlId ){
		case OVL_SPEECH:   *n = countRows( ES_Speech ); return ES_Speech;
		case OVL_ONSCREEN: *n = countRows( ES_OnScreen ); return ES_OnScreen;
		case OVL_QUEST:    *n = countRows( ES_Quest ); return ES_Quest;
	}
	*n = 0; return 0;
}

// ES_GCInfoName
const char* ES_GCInfoName( int gc )
{
	switch( gc ){
		case 0: return "Ninguno (omitido)";
		case 1: return "Autoguardado";
		case 2: return "Equipo Vinculado";
		case 3: return "Ca\xED""da de Objetos";
		case 4: return "Sin Esfuerzo";
		case 5: return "Vivir de la Tierra";
		case 6: return "Imposible";
		case 7: return "Prohibici\xF3n";
		case 8: return "Contacto Total";
		case 9: return "Estirpe Nocturna";
		case 10: return "Cortar y Rajar";
		case 11: return "Vacunado";
		case 12: return "Ese es Mi Secreto";
		case 13: return "Sin Regeneraci\xF3n";
		case 14: return "Manos Limpias";
		case 15: return "Edad de Hielo";
		case 16: return "D\xED""a de la Marmota";
		case 17: return "Monstruos Duros";
		case 18: return "Objetos Eternos";
		case 19: return "Sin Mapa";
		case 20: return "Da\xF1o Doble";
		case 21: return "No Ver el Mal";
		case 22: return "Muerte Negra";
		case 23: return "Mala Suerte";
		case 24: return "Hierro Despiadado";
		case 25: return "Aceleraci\xF3n";
		case 26: return "Ascetismo";
		case 27: return "Exterminador";
		case 28: return "Supermutante";
		case 29: return "Militar del Enclave";
		default: return nullptr;
	}
}

// ES_GCInfoDesc
const char* ES_GCInfoDesc( int gc )
{
	switch( gc ){
		case 0: return "Ninguno (omitido)";
		case 1: return "Autoguardado\n\n\nAltera el estilo de juego\n\nElimina la necesidad de guardar la partida manualmente; el guardado es autom\xE1tico, igual que en el modo multijugador.";
		case 2: return "Equipo Vinculado\n\n\nA\xF1""ade desaf\xEDo\n\nHace imposible equipar o desequipar objetos durante la batalla (salvo las ranuras de mano).";
		case 3: return "Ca\xED""da de Objetos\n\n\nA\xF1""ade desaf\xEDo\n\nAl morir sueltas los objetos equipados.\n\nAdvertencia: si los objetos ca\xED""dos no se recuperan en la misma sesi\xF3n de juego, desaparecer\xE1n.";
		case 4: return "Sin Esfuerzo\n\n\nHace el juego m\xE1s f\xE1""cil\n\nLos monstruos solo te causan la mitad del da\xF1o.\nM\xE1s f\xE1""cil imposible.";
		case 5: return "Vivir de la Tierra\n\n\nA\xF1""ade desaf\xEDo\n\nLos aldeanos no te vender\xE1n ning\xFAn objeto.\n\nPero no dejar\xE1n de prestar sus servicios: charla, di\xE1logos de misi\xF3n, reparaci\xF3n, identificaci\xF3n, encantamiento, creaci\xF3n, engarce y recarga.";
		case 6: return "Imposible\n\n\nHace el juego m\xE1s dif\xED""cil\n\nLos monstruos te causan el doble de da\xF1o.\nM\xE1s dif\xED""cil imposible.";
		case 7: return "Prohibici\xF3n\n\n\nA\xF1""ade desaf\xEDo\n\nLos monstruos ya no sueltan elixires de atributo al azar\nNota: la ventaja Bebedor Empedernido seguir\xE1 dando elixires de monstruos \xFAnicos";
		case 8: return "Contacto Total\n\n\nHace el juego m\xE1s f\xE1""cil\n\nLos monstruos con ataques a distancia no retroceden.";
		case 9: return "Estirpe Nocturna\n\n\nTe convierte en vampiro\n\nVives y mueres por la sangre. Tu hambre es insaciable, pero tienes todas las herramientas para cazar a los d\xE9""biles\n\nEsto cambia la jugabilidad.\nNo usas objetos y dependes de tus poderes innatos.";
		case 10: return "Cortar y Rajar\n\n\nHace el juego m\xE1s f\xE1""cil\n\nYa no tienes que cambiar de tipo de arma (afilada o contundente) para adaptarte al tipo de monstruo. Todas las armas causan da\xF1o est\xE1ndar a todas las especies de monstruo.";
		case 11: return "Vacunado\n\n\nHace el juego m\xE1s f\xE1""cil\n\nLos monstruos pierden todas las inmunidades, y no hace falta cambiar de hechizo: todo tipo de hechizo funciona.\nMaldici\xF3n de Piedra, Esp\xEDritu \xD3seo, Elemental y los hechizos sagrados no se ven afectados.";
		case 12: return "Ese es Mi Secreto\n\n\nHace el juego m\xE1s f\xE1""cil\n\nFuria no tiene tiempo de recarga y puede lanzarse de nuevo en cuanto termina.";
		case 13: return "Sin Regeneraci\xF3n\n\n\nA\xF1""ade desaf\xEDo\n\nEl personaje no tiene regeneraci\xF3n b\xE1sica de vida ni de man\xE1.";
		case 14: return "Manos Limpias\n\n\nA\xF1""ade desaf\xEDo\n\nLos monstruos no sueltan objetos que el personaje pueda equipar.\nEl jugador debe conseguirlos comprando o encantando.";
		case 15: return "Edad de Hielo\n\n\nCambio cosm\xE9tico\n\nLos niveles de la mazmorra parecen sumidos en pleno invierno; todo est\xE1 helado y congelado.\n\xBF""Alguna vez has imaginado c\xF3mo ser\xED""a el Infierno congelado?";
		case 16: return "D\xED""a de la Marmota\n\n\nAltera el estilo de juego\n\nSe genera siempre la misma mazmorra, poblada por los mismos monstruos. Puedes jugar y mejorar tu ritmo cada vez que juegas.";
		case 17: return "Monstruos Duros\n\n\nHace el juego m\xE1s dif\xED""cil\n\nLos monstruos tienen un +200% en puntos de vida.";
		case 18: return "Objetos Eternos\n\n\nHace el juego m\xE1s f\xE1""cil\n\nLos objetos no se destruir\xE1n si la durabilidad llega a cero. En su lugar, quedar\xE1n inservibles hasta ser reparados.";
		case 19: return "Sin Mapa\n\n\nA\xF1""ade desaf\xEDo\n\nEl automapa no est\xE1 disponible\nTendr\xE1s que orientarte por las mazmorras sin depender de \xE9l\n\n\xBFYa te sientes perdido?";
		case 20: return "Da\xF1o Doble\n\n\nHace el juego m\xE1s f\xE1""cil\n\nTus ataques causan el doble de da\xF1o a los monstruos\n\nAdvertencia: puede volverse decepcionantemente f\xE1""cil.\nNo elijas esto si quieres conservar la emoci\xF3n del combate.";
		case 21: return "No Ver el Mal\n\n\nA\xF1""ade desaf\xEDo\n\nLa Videncia no resalta a los monstruos en la oscuridad.";
		case 22: return "Muerte Negra\n\n\nEst\xE1s infectado\n\nLa plaga de la Muerte Negra se ha apoderado de ti. Desarrollar\xE1 lentamente s\xEDntomas adversos que acabar\xE1n mat\xE1ndote de forma inevitable.\n\nNo puedes curarla, no puedes sanarla y no puedes detenerla. Con el tiempo se volver\xE1 cada vez m\xE1s severa. No hay escapatoria de esta enfermedad mortal.";
		case 23: return "Mala Suerte\n\n\nA\xF1""ade desaf\xEDo\n\nLa suerte tiende a agotarse tarde o temprano. La tuya ni siquiera empez\xF3.\n\nEmpiezas la partida con todos los atributos a 5. Solo obtienes 2 puntos de atributo al subir de nivel. Las habilidades de b\xFAsqueda m\xE1gica, la experiencia ganada y la capacidad de hallar oro se reducen un 75%. Empiezas la partida sin ning\xFAn objeto.\n\nNinguna ventaja te ayuda con la experiencia, la ca\xED""da de elixires, la b\xFAsqueda de objetos m\xE1gicos ni los atributos al subir de nivel.";
		case 24: return "Hierro Despiadado\n\n\nA\xF1""ade desaf\xEDo\n\nEl Ironman cl\xE1sico de Diablo era distinto.\n\nNo hab\xED""a aumento de atributos por nivel, ni experiencia extra, ni aceites ni identificaciones de los jefes. Tampoco mejora en la b\xFAsqueda m\xE1gica.\n\nEsta Alteraci\xF3n te devuelve a esas ra\xED""ces.";
		case 25: return "Aceleraci\xF3n\n\n\nHace el juego m\xE1s f\xE1""cil\n\nLa experiencia se multiplica por 2.";
		case 26: return "Ascetismo\n\n\nA\xF1""ade desaf\xEDo\n\nLa partida se guarda autom\xE1ticamente.\n\nLos objetos se sueltan al morir. No puedes resucitar en la ciudad (has de crear una partida nueva) y por eso se pierden todos los objetos ca\xED""dos.\n\nEs como el modo Hardcore, pero en vez de perder el personaje, pierdes los objetos equipados.";
		case 27: return "Exterminador\n\n\nEres una unidad de la serie Cyberdyne Systems. Modelo 101, infiltrador. Modo de lectura-escritura de la CPU activado. Enviado al pasado para ejecutar la misi\xF3n.\n\nObjetivo principal: Uber Diablo.\n\nObjetivo secundario: exterminar monstruos.\n\nCondici\xF3n: parecer humano ante los sujetos nativos.\n\nMejoras b\xE1sicas instaladas. Mejoras adicionales disponibles mediante autoaprendizaje.";
		case 28: return "Supermutante\n\n\nTu cuerpo puede portar armas que partir\xED""an en dos a un hombre normal.\n\nAmetralladoras.\n\nCosas que no deber\xED""an existir en este mundo. Ya no lanzas hechizos. No lo necesitas.\n\nCuando aprietas el gatillo, la r\xE1""faga desgarra a la cr\xED""a del infierno como papel en una tormenta.";
		case 29: return "Militar del Enclave\n\n\nSoldado de las Fuerzas Armadas del Enclave, entrenado para exterminar mutantes e impureza gen\xE9tica.\n\nSe halla varado en un mundo que jam\xE1s conoci\xF3 el fuego nuclear, pero que tiene inmundicia de otra clase: la cr\xED""a del infierno.\n\nEl enemigo ha cambiado. El prop\xF3sito no.\n\nHabilidades: empu\xF1""a armas de energ\xED""a y despliega drones de combate. Diestro en la guerra elemental.";
		default: return nullptr;
	}
}

